head.script:
/**
* PSP007F05.xml(소송비용계산 - 송달료 계산)
* ASIS-ECF304_2.jsp, ECF304_2.js
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.20.   김기오       [NELS]최초 생성
*  2025.11.06.                [25A-PSP-0081] 특허청의 지식재산처 승격에 따른 개선  
* ============= ============ ==========================
*/

/* ==================================
 * 1.전역변수 선언부
 * ==================================*/
scwin.dlvrAmtInfo = {
    sdFeeCalcBySaGbn: "",// 사건구분별 송달료 계산식
    cmbSaType: "",

    sdFeeHgCnt: "", //항고: "",재항고사건
    cmbHgType: "",

    sdFeeSinCntWCV: "", //(민사)신청사건 //asis - sdFeeWcvSinCnt
    sdFeeWptSinCnt: "", //(특허)신청사건
    cmbSinType: "",

    sdFeeCntWCV: "",  //민사 사건 종류
    sdFeeHgCntWCV: "",  //민사 항고사건 종류

    sdFeeCntWKS: "",  //가사 사건 종류
    sdFeeHgCntWKS: "",  //가사 항고사건 종류
    sdFeeBSCntWKS: "",     //가사 (라류)가사사건 종류
    cmbSaTypeWKS: "",
    cmbSinTypeWks: "",

    sdFeeSinCntWKS: "",
    sdFeeCntWHS: "",  //행정 사건 종류
    sdFeeHgCntWHS: "",  //행정 항고사건 종류

    sdFeeCntWPT: "",  //특허 사건 종류
    sdFeeHgCntWPT: "",  //특허 항고사건 종류

    sdFeeCntWHP: "",  //회생파산관련 사건 종류
    sdFeeAmtCntWHP1: "",  //회생파산관련 신청사건 종류
    sdFeeAmtCntWHP2: "",  //회생파산관련 신청사건 종류
    sdFeeAmtCntWHP3: "",  //회생파산관련 신청사건 종류
    sdFeeAmtCntWHP4: "",  //회생파산관련 신청사건 종류
    sdFeeAmtCntWHP5: "",  //회생파산관련 신청사건 종류
    sdFeeAmt: "",
    whpSinType: "",
    sdFeeHgCntWHP: "",  //회생파산관련 항고사건 종류

    jhwgjbsSinType: "",
    sdFeeCntJHWGJ: "",
    sdFeeAmtCntJHWGJ1: "",  //민사집행관련 사건 종류
    sdFeeAmtCntJHWGJ2: "",  //민사집행관련 사건 종류
    sdFeeAmtCntJHWGJ3: "",  //민사집행관련 사건 종류
    sdFeeAmtCntJHWGJ4: "",  //민사집행관련 사건 종류
    sdFeeAmtCntJHWGJ5: "",  //민사집행관련 사건 종류
    sdFeeAmtCntJHWGJ6: "",  //민사집행관련 사건 종류
    sdFeeHgCntJHWGJ: "",

    sdFeeCntGW: "",
    sdFeeAmtCntGW1: "",  //과태료관련 사건 종류
    sdFeeHgCntGW: "",

    sdFeeCntWETBS: "",
    sdFeeAmtCntWETBS1: "",  //비송관련 사건 종류
    sdFeeAmtCntWETBS2: "",  //비송관련 사건 종류
    sdFeeHgCntWETBS: "",

    // validator
    chk: "",
    chkW: "",
    chkI: "",
    calculRev: "", // 원고,피고 수 반대로 계산

    //TOBE 추가
    mainFlag: "",
    detailFlag: "",
    isJintLwst: false,

    strDlvrChrg: "",
    strDlvrChrgForWPT: "",
    sdFeeNbRule: "",
    dcMultiValue: "",

};

scwin.componentInfo = {
    sbxClassInfo: [],
    onOffComponetList: [],
    sbxObjectList: [],
    calcBtnObjectList: [],
}

/* ==================================
* 2.페이지 Onload/Unload 선언부
* ==================================*/
/**
 * 화면 pageload 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.21.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */

scwin.onpageload = function () {
    _debug("[PSP007F05#onpageload] 로드됨. frame ID : " + $p.getFrameId() + " ");
    // var wfparam = psp.getPageInit($p);
    // _debug("[PSP007F05#onpageload]", "<page param>", wfparam);
    scwin.init();

};

scwin.onpageunload = function () {

};

/* ==================================
 * 3.페이지 초기화 선언부
 * ==================================*/

/**
* 페이지 초기화
*
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.21.   김기오       [NELS]최초 생성
*  2023.07.27.   김기오       컴포넌트 제어 로직 추가
* ============= ============ ==========================
*/
scwin.init = function () {
    console.log(1);

    scwin.componentInfo.sbxClassInfo = ["", "", "", "", "", ""];
    scwin.componentInfo.onOffComponetList = [sbx_apalCsType, sbx_aplyCsType, sbx_hskpAplyCsType, sbx_hskpCsType, grp_rhblBnkpCsType, grp_execNonLwstCsType];
    scwin.componentInfo.sbxObjectList = [sbx_apalCsType, sbx_aplyCsType, sbx_hskpAplyCsType, sbx_hskpCsType, sbx_rhblBnkpCsType, sbx_execNonLwstCsType];
    scwin.componentInfo.calcBtnObjectList = [btn_calcExecNonLwst, btn_calcClmnt, btn_calcAcsd, btn_calcIntrps, btn_calc];

    grp_prncmtLwstDvs.hide("");

    scwin.handleSbxList();

    grp_rhblBnkpCsType.hide("");
    grp_execNonLwstCsType.hide("");
    grp_intrps.hide("");
    grp_trgtOrg.hide("");
    sbx_ptntAcsdDvsCd.hide("");
    scwin.handleBtnList(2);


    dma_parentInfo.setJSON($p.parent().dma_parentInfo.getJSON());
    if (scutilo.isEmpty(dma_parentInfo.get("elctnLwstTaskTypCd"))) {
        dma_parentInfo.set("elctnLwstTaskTypCd", "PCV");
    }

    //본안 소송구분 selectBox 초기세팅
    var prncmtLwstDvsCdList = [
        { "label": "전자", "value": psp.C.ELC_SOSONG },
        { "label": "종이", "value": psp.C.PAPER_SOSONG },
    ]
    dlt_prncmtLwstDvsCd.setJSON(prncmtLwstDvsCdList);

    //화면Load 시 첫 번째 입력필드에 마우스커스 포커스
    sbx_elctnLwstTaskTypCd.focus();

    console.log(1);

    scwin.retrieveDlvrCalcBasInfo();
}

/* ==================================
* 4.컴포넌트 이벤트 처리부
* ==================================*/

/**
 * 소송유형 변경에 따른 이벤트
 * ASIS-fnChgSosongTypcd 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.21.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */

scwin.sbx_elctnLwstTaskTypCd_onviewchange = function (info) {
    scwin.fnChangeLwstTaskTypCd();
};

/**
 * 사건구분 변경에 따른 이벤트
 * ASIS-fnSaTypeChange 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.21.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_csType_onviewchange = function (info) {
    scwin.fnChangeCsTypCd();
};

/**
* 상세사건 selectBox onviewchange event
* ASIS-fnHgTypeChange, fnSinTypeChange, fnSosongGbnChange
*      fnWksSinTypeChange, fnWhpSinTypeChange, fnJhwgjSinTypeChange
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.sbx_apalCsType_onviewchange = function (info) {
    scwin.fnChangeDetailCsTypCd("APAL");
};

scwin.sbx_aplyCsType_onviewchange = function (info) {
    scwin.fnChangeDetailCsTypCd("CVLCS");
};

scwin.sbx_hskpAplyCsType_onviewchange = function (info) {
    scwin.fnChangeDetailCsTypCd("HSKP_APLY");
};

scwin.sbx_hskpCsType_onviewchange = function (info) {
    scwin.fnChangeDetailCsTypCd("HSKP_EXCP");
};

scwin.sbx_rhblBnkpCsType_onviewchange = function (info) {
    scwin.fnChangeDetailCsTypCd("RHBL_BNKP");
};

scwin.sbx_execNonLwstCsType_onviewchange = function (info) {
    scwin.fnChangeDetailCsTypCd("EXEC_NON_LWST");
};

/**
* 본안 소송구분코드 변경에 따른 처리 Method
* ASIS - fnSosongGbnChange 호출
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.sbx_prncmtLwstDvsCd_onviewchange = function (info) {
    scwin.setDefaultCnt();
};

/**
* 특허 비고구분 변경에 따른 처리 Method
* ASIS - fnPigoGbnChange 호출
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.sbx_ptntAcsdDvsCd_onviewchange = function (info) {
    scwin.fnChangePtntAcsdDvsCd(info.newValue);
};

/**
* 신청사건 종류 계산 버튼 onclick event
* ASIS - calcSdFee 호출
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.btn_calcExecNonLwst_onclick = function (e) {
    scwin.calcDlvrChrg();
};

/**
* 원고라인 계산 버튼 onclick event
* ASIS - calcSdFee 호출
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.btn_calcClmnt_onclick = function (e) {
    scwin.calcDlvrChrg();
};

/**
* 피고라인 계산 버튼 onclick event
* ASIS - calcSdFee 호출
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.btn_calcAcsd_onclick = function (e) {
    scwin.calcDlvrChrg();
};

/**
* 이해관계인 계산 버튼 onclick event
* ASIS - calcSdFee 호출
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.btn_calcIntrps_onclick = function (e) {
    scwin.calcDlvrChrg();
};

/**
* 계산 버튼 onclick event
* ASIS - calcSdFee 호출
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.btn_calc_onclick = function (e) {
    scwin.calcDlvrChrg();
};

/**
 * 원고 inputBox onkeyDown Event
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_clmntCnt_onkeydown = function (e) {
    if (e.keyCode == "13") {
        e.preventDefault();
        scwin.calcDlvrChrg();
    }
};

/**
 * 피고 inputBox onkeyDown Event
 * ASIS-fnCalcSdAmt 호출
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_acsdCnt_onkeydown = function (e) {
    if (e.keyCode == "13") {
        e.preventDefault();
        scwin.calcDlvrChrg();
    }
};

/**
 * 이해관계인 inputBox onkeyDown Event
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_intrpsCnt_onkeydown = function (e) {
    if (e.keyCode == "13") {
        e.preventDefault();
        scwin.calcDlvrChrg();
    }
};

/**
 * 대상기관 금액 inputBox onkeyDown Event
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.ibx_trgtOrgAmt_onkeydown = function (e) {
    if (e.keyCode == "13") {
        e.preventDefault();
        scwin.calcDlvrChrg();
    }
};

/* ==================================
* 5. 사용자 정의 이벤트
* ==================================*/

/**
 * 송달료 계산 기본 정보 조회
 * ASIS-fnGetCalcBaseInfo
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.20.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.retrieveDlvrCalcBasInfo = function () {
    com.executeSubmission(sbm_retrieveDlvrCalcBasInfo);
}

/**
 * 송달료 계산 사건 상세 계산 정보 조회
 * ASIS-fnGetDataSdAmt
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.20.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.retrieveDetailAmtInfo = function () {
    dma_search.set("elpEcdocNo", dma_parentInfo.get("elpEcdocNo"));
    dma_search.set("calcType", "dlvrChrg");
    com.executeSubmission(sbm_retrieveCsCalcInfo);
}

/**
* 소송유형 변경에 따른 처리 Method
* ASIS-fnChgSosongTypcd
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.20.   김기오       [NELS]최초 생성
*  2024.04.09.   김기오       사건구분 변경로직 주석처리
* ============= ============ ==========================
*/
scwin.fnChangeLwstTaskTypCd = function (option) {
    //가사
    var lwstTaskTypCd = sbx_elctnLwstTaskTypCd.getValue();
    if (psp.C.SO_KIND_PKS == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWKS"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWKS"));
    }//행정
    else if (psp.C.SO_KIND_PHS == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWHS"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWHS"));
    }//특허
    else if (psp.C.SO_KIND_PPT == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWPT"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWPT"));
    }//회생파산
    else if (psp.C.SO_KIND_PHP == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWHP"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWHP"));
        spn_clmnt.setValue("채무자");
        ibx_clmntCnt.setTitle("채무자수");
        spn_acsd.setValue("채권자");
        ibx_acsdCnt.setTitle("채권자수");
    }//민사집행
    else if (psp.C.SO_KIND_PJG == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntJHWGJ"));
        //TODO 해당변수가없음 확인필요
        scwin.setLocalVar("sdFeeHgCnt", scutilo.isEmpty(scwin.getLocalVar("sdFeeHgCntJHWGJ")) ? "" : scwin.getLocalVar("sdFeeHgCntJHWGJ"));
        spn_clmnt.setValue("신청인");
        ibx_clmntCnt.setTitle("신청인");
        spn_acsd.setValue("상대방");
        ibx_acsdCnt.setTitle("상대방수");
    }//과태료
    else if (psp.C.SO_KIND_PGW == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntGW"));
        //TODO 해당변수가없음 확인필요
        scwin.setLocalVar("sdFeeHgCnt", scutilo.isEmpty(scwin.getLocalVar("sdFeeHgCntGW")) ? "" : scwin.getLocalVar("sdFeeHgCntGW"));
        spn_clmnt.setValue("신청인");
        ibx_clmntCnt.setTitle("신청인수");
        spn_acsd.setValue("검사");
        ibx_acsdCnt.setTitle("검사수");
    }//비송
    else if (psp.C.SO_KIND_PEB == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWETBS"));
        scwin.setLocalVar("sdFeeHgCnt", scutilo.isEmpty(scwin.getLocalVar("sdFeeHgCntWETBS")) ? "" : scwin.getLocalVar("sdFeeHgCntWETBS"));
        spn_clmnt.setValue("신청인");
        ibx_clmntCnt.setTitle("신청인수");
        spn_acsd.setValue("피신청인");
        ibx_acsdCnt.setTitle("피신청인수");
    } else {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWCV"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWCV"));
    }

    dlt_csTypeList.removeAll();
    dlt_apalDetailCsTypeList.removeAll();
    dlt_cvlcsAplyDetailCsTypeList.removeAll();
    dlt_hskpAplyDetailCsTypeList.removeAll();
    dlt_hskpBsDetailCsTypeList.removeAll();

    if (!scwin.getLocalVar("sdFeeHgCnt")) {
        scwin.setLocalVar("sdFeeHgCnt", 0);
    }

    var tmpList = scwin.getLocalVar("sdFeeCalcBySaGbn");
    var hgTmpList = scwin.getLocalVar("sdFeeHgCnt");

    //사건 종류
    for (var i = 0; i < tmpList.length; i++) {
        var rowData = {
            "label": tmpList[i].saGbnTxt,
            "value": tmpList[i].saGbnValue,
        }
        dlt_csTypeList.setRowJSON(i, rowData);
    }

    //항고사건 종류
    var apalMaxByte = 0;
    for (var i = 0; i < hgTmpList.length; i++) {

        var rowData = {
            "label": (psp.C.JSHANGGO != hgTmpList[i].docCd ? "" : "즉시 ") + hgTmpList[i].saTxt,
            "value": hgTmpList[i].docCd,
        }
        dlt_apalDetailCsTypeList.setRowJSON(i, rowData);
        var labelByte = scwin.getStrByte(rowData.label);
        if (labelByte > apalMaxByte) {
            apalMaxByte = labelByte;
        }
    }
    scwin.handleSbxList(0, apalMaxByte);
    //가사
    if (psp.C.SO_KIND_PKS == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWKS"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWKS"));
    }//행정
    else if (psp.C.SO_KIND_PHS == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWHS"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWHS"));
    }//특허
    else if (psp.C.SO_KIND_PPT == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWPT"));
        //scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWPT"));
    }//회생파산
    else if (psp.C.SO_KIND_PHP == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWHP"));
        spn_clmnt.setValue("채무자");
        ibx_clmntCnt.setTitle("채무자수");
        spn_acsd.setValue("채권자");
        ibx_acsdCnt.setTitle("채권자수");
    }//민사집행
    else if (psp.C.SO_KIND_PJG == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntJHWGJ"));
        //TODO 해당변수가없음 확인필요
        scwin.setLocalVar("sdFeeHgCnt", scutilo.isEmpty(scwin.getLocalVar("sdFeeHgCntJHWGJ")) ? "" : scwin.getLocalVar("sdFeeHgCntJHWGJ"));
    }//과태료
    else if (psp.C.SO_KIND_PGW == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntGW"));
        //TODO 해당변수가없음 확인필요
        scwin.setLocalVar("sdFeeHgCnt", scutilo.isEmpty(scwin.getLocalVar("sdFeeHgCntGW")) ? "" : scwin.getLocalVar("sdFeeHgCntGW"));
    }//비송
    else if (psp.C.SO_KIND_PEB == lwstTaskTypCd) {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWETBS"));
        scwin.setLocalVar("sdFeeHgCnt", scutilo.isEmpty(scwin.getLocalVar("sdFeeHgCntWETBS")) ? "" : scwin.getLocalVar("sdFeeHgCntWETBS"));
        //TODO LABEL 수정 채무자, 채권자
    } else {
        scwin.setLocalVar("sdFeeCalcBySaGbn", scwin.getLocalVar("sdFeeCntWCV"));
        scwin.setLocalVar("sdFeeHgCnt", scwin.getLocalVar("sdFeeHgCntWCV"));
    }

    var wcvTmpList = scwin.getLocalVar("sdFeeSinCntWCV");

    //민사신청사건 종류
    var cvlcsAplyMaxByte = 0;
    for (var j = 0; j < wcvTmpList.length; j++) {
        if (wcvTmpList[j].saNmCd == "200") {
            var rowData1 = {
                "label": wcvTmpList[j].saTxt + "(계쟁물)",
                "value": wcvTmpList[j].saNmCd,
            }
            var rowData2 = {
                "label": wcvTmpList[j].saTxt + "(임시지위)",
                "value": wcvTmpList[j].saNmCd + "Im",
            }
            dlt_cvlcsAplyDetailCsTypeList.setRowJSON(dlt_cvlcsAplyDetailCsTypeList.getTotalRow(), rowData1);
            dlt_cvlcsAplyDetailCsTypeList.setRowJSON(dlt_cvlcsAplyDetailCsTypeList.getTotalRow(), rowData2);
            var labelByte = scwin.getStrByte(rowData2.label);
            if (labelByte > cvlcsAplyMaxByte) {
                cvlcsAplyMaxByte = labelByte;
            }

        } else {
            var rowData = {
                "label": wcvTmpList[j].saTxt,
                "value": wcvTmpList[j].saNmCd,
            }
            dlt_cvlcsAplyDetailCsTypeList.setRowJSON(dlt_cvlcsAplyDetailCsTypeList.getTotalRow(), rowData);
            var labelByte = scwin.getStrByte(rowData.label);
            if (labelByte > cvlcsAplyMaxByte) {
                cvlcsAplyMaxByte = labelByte;
            }
        }
    }
    scwin.handleSbxList(1, cvlcsAplyMaxByte);

    if (psp.C.SO_KIND_PKS == lwstTaskTypCd) {
        //라류가사사건 종류
        var hskpCsMaxByte = 0;
        var tmpKsList = scwin.getLocalVar("sdFeeBSCntWKS");
        for (var i = 0; i < tmpKsList.length; i++) {
            var rowData = {
                "label": tmpKsList[i].saTxt,
                "value": tmpKsList[i].saNmCd,
            }
            dlt_hskpBsDetailCsTypeList.setRowJSON(dlt_hskpBsDetailCsTypeList.getTotalRow(), rowData);
            var labelByte = scwin.getStrByte(rowData.label);
            if (labelByte > hskpCsMaxByte) {
                hskpCsMaxByte = labelByte;
            }
        }
        scwin.handleSbxList(3, hskpCsMaxByte);

        //가사신청사건 종류
        var hskpAplyCsMaxByte = 0;
        var tmpKsAplyList = scwin.getLocalVar("sdFeeSinCntWKS");
        for (var i = 0; i < tmpKsAplyList.length; i++) {
            var rowData = {
                "label": tmpKsAplyList[i].saTxt,
                "value": tmpKsAplyList[i].saNmCd,
            }
            dlt_hskpAplyDetailCsTypeList.setRowJSON(dlt_hskpAplyDetailCsTypeList.getTotalRow(), rowData);
            var labelByte = scwin.getStrByte(rowData.label);
            if (labelByte > hskpAplyCsMaxByte) {
                hskpAplyCsMaxByte = labelByte;
            }
        }
        scwin.handleSbxList(2, hskpAplyCsMaxByte);
    }

    // if (!scutilo.isEmpty(option)) {
    //     sbx_csType.setValue(option);
    // }
    //사건 종류 변경에 따른 처리
    scwin.fnChangeCsTypCd();
}

/**
* 사건구분 변경에 따른 처리 Method
* ASIS-fnSaTypeChange
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.21.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.fnChangeCsTypCd = function () {
    var csTypCd = sbx_csType.getValue();
    ibx_clmntCnt.setValue("");
    ibx_acsdCnt.setValue("");
    spn_rslt.setValue("");
    ibx_acsdCnt.show("");
    spn_acsdCnt.show("");

    //항고, 재항고 사건에 대한 화면 컴포넌트 설정
    if (csTypCd == "HG") {
        //항고 공통
        //항고재사건종류 bind후 데이터 화면에 show
        sbx_apalCsType.setSelectedIndex(0);
        scwin.handleSbxList([0]);

        //본안소송구분 초기화 후 화면에 show
        sbx_prncmtLwstDvsCd.setSelectedIndex(0);
        grp_prncmtLwstDvs.show("");

        grp_clmnt.show("");

        //특허피고구분 숨김
        sbx_ptntAcsdDvsCd.hide("");
        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        ibx_acsdCnt.setValue("");

        if (psp.C.SO_KIND_PHP == sbx_elctnLwstTaskTypCd.getValue()) {
            scwin.handleBtnList(1);
        }
        else {
            btn_calc.show("");
            spn_acsd.show("")
            grp_acsd.show("");
            //sbx_apalCsType.focus();
            scwin.handleBtnList(2);
        }

        scwin.fnChangeDetailCsTypCd("APAL")
    }
    //신청사건에 따른 화면 컴포넌트 설정(가사 신청사건은 제외)
    else if (csTypCd == "SC") {
        if (psp.C.SO_KIND_PCV == sbx_elctnLwstTaskTypCd.getValue()) {
            sbx_aplyCsType.setSelectedIndex(0);
            scwin.handleSbxList([1]);
            //sbx_aplyCsType.focus();
        }
        else {
            sbx_aplyCsType.hide("");
            scwin.handleSbxList();
        }
        //본안소송구분 초기화 후 화면에 show
        sbx_prncmtLwstDvsCd.setSelectedIndex(0);
        grp_prncmtLwstDvs.show("");

        //다음 예상 변경값인 신청서 종류에 포커싱한 후 안내문구 설정
        //sbx_aplyCsType.focus();

        grp_clmnt.show("");
        //특허피고구분 숨김
        sbx_ptntAcsdDvsCd.hide("");
        spn_acsd.show("")
        ibx_acsdCnt.setValue("");
        ibx_acsdCnt.show("");
        spn_acsdCnt.show("");
        grp_acsd.show("");
        scwin.handleBtnList(2);

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        btn_calc.show("");

        scwin.fnChangeLabel(csTypCd);
    } //가사 신청사건
    else if (csTypCd == "WKS_SC") {

        sbx_hskpAplyCsType.setSelectedIndex(0);
        scwin.handleSbxList([2]);

        //본안소송구분 초기화 후 화면에 show
        sbx_prncmtLwstDvsCd.setSelectedIndex(0);
        grp_prncmtLwstDvs.show("");

        grp_clmnt.show("");

        spn_acsd.show("");
        //특허피고구분 숨김
        sbx_ptntAcsdDvsCd.hide("");
        ibx_acsdCnt.setValue("");
        grp_acsd.show("");
        scwin.handleBtnList(2);

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        //다음 예상 변경값인 신청서 종류에 포커싱한 후 안내문구 설정
        //sbx_hskpAplyCsType.focus();
        scwin.fnChangeLabel(csTypCd);
    }//특허1심사건
    else if (csTypCd == "WPT") {

        scwin.handleSbxList();

        grp_prncmtLwstDvs.hide("");

        grp_clmnt.show("");

        spn_acsd.show("");
        //특허피고구분 show
        sbx_ptntAcsdDvsCd.setSelectedIndex(0);
        sbx_ptntAcsdDvsCd.show("");
        ibx_acsdCnt.setValue("");

        grp_acsd.show("");
        scwin.handleBtnList(2);

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        //sbx_ptntAcsdDvsCd.focus();
        scwin.fnChangePtntAcsdDvsCd();

    }//특허 상고 심사건
    else if (csTypCd == "SG_WPT") {

        scwin.handleSbxList();

        grp_prncmtLwstDvs.hide("");
        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        grp_clmnt.show("");

        spn_acsd.show("");
        //특허피고구분 show
        sbx_ptntAcsdDvsCd.setSelectedIndex(0);
        sbx_ptntAcsdDvsCd.show("");
        ibx_acsdCnt.setValue("");
        grp_acsd.show("");
        scwin.handleBtnList(2);

        //sbx_ptntAcsdDvsCd.focus();
        scwin.fnChangePtntAcsdDvsCd();

    }//가사비송 라류
    else if (csTypCd == "WKS_BS4") {

        sbx_hskpCsType.setSelectedIndex(0);
        scwin.handleSbxList([3]);

        grp_prncmtLwstDvs.hide("");

        grp_clmnt.show("");
        scwin.handleBtnList(1);

        ibx_acsdCnt.setValue("");
        grp_acsd.hide("");

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        scwin.fnChangeLabel(csTypCd);

    }//가사 보전처분
    else if (csTypCd == "BJ") {
        if (psp.C.SO_KIND_PCV == sbx_elctnLwstTaskTypCd.getValue()) {
            sbx_aplyCsType.setSelectedIndex(0);
            scwin.handleSbxList([1]);
            //sbx_aplyCsType.focus();
        }
        else {
            sbx_aplyCsType.hide("");
            scwin.handleSbxList();
        }

        //본안소송구분 초기화 후 화면에 show
        sbx_prncmtLwstDvsCd.setSelectedIndex(0);
        grp_prncmtLwstDvs.show("");

        grp_clmnt.show("");

        spn_acsd.show("");
        //특허피고구분은 숨김
        sbx_ptntAcsdDvsCd.hide("");
        ibx_acsdCnt.setValue("");
        grp_acsd.show("");
        scwin.handleBtnList(2);

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        scwin.fnChangeLabel(csTypCd);

    } // 회생파산
    else if ("PH" == csTypCd || "PF" == csTypCd || "BH" == csTypCd || "BF" == csTypCd || "NH" == csTypCd) {
        ///신청사건 종류 변경 확인
        if ("PH" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntWHP1"));
        } else if ("PF" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntWHP2"));
        } else if ("BH" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntWHP3"));
        } else if ("BF" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntWHP4"));
        } else if ("NH" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntWHP5"));
        }
        //회생파산부분 신청사건콤보 출력
        dlt_rhblBnkpAplyDetailCsTypeList.removeAll();
        var rhblBnkpAplyCsMaxByte = 0;
        var tmpList = scwin.getLocalVar("sdFeeAmt");
        for (var i = 0; i < tmpList.length; i++) {
            var rowData = {
                "label": tmpList[i].saTxt,
                "value": tmpList[i].saNmCd,
            };
            dlt_rhblBnkpAplyDetailCsTypeList.setRowJSON(i, rowData);
            var labelByte = scwin.getStrByte(rowData.label);
            if (labelByte > rhblBnkpAplyCsMaxByte) {
                rhblBnkpAplyCsMaxByte = labelByte;
            }
        }
        scwin.handleSbxList(4, rhblBnkpAplyCsMaxByte);
        sbx_rhblBnkpCsType.setSelectedIndex(0);
        scwin.handleSbxList([4]);

        //싱속재산파산신청서 개선
        var ofdocDvsCd = dma_csCalcInfo.get("ofdocDvsCd");
        if (ofdocDvsCd == psp.C.INHERFTPSSIN) {
            sbx_rhblBnkpCsType.setValue(dma_csCalcInfo.get("whpSinType"));
        }

        grp_prncmtLwstDvs.hide("");

        ibx_clmntCnt.setValue("1");
        grp_clmnt.show("");
        scwin.handleBtnList(1);

        //회생파산 채권자값이 필수로 설정되어야 함
        ibx_acsdCnt.setValue("1");
        grp_acsd.hide("");

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        scwin.fnChangeLabel(csTypCd, scwin.fnChangeDetailCsTypCd, "RHBL_BNKP")
    } //집행비송
    else if ("JMKC" == csTypCd || "BSD" == csTypCd || "BSH" == csTypCd || "GJ" == csTypCd || "JSCM" == csTypCd) {
        ///사건 종류 변경 확인
        if ("JMKC" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntJHWGJ4"));
        } else if ("BSD" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntWETBS1"));
        } else if ("BSH" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntWETBS2"));
        } else if ("GJ" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntJHWGJ6"));
        } else if ("JSCM" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntJHWGJ5"));
        }//집행비송부분 신청사건콤보 출력
        dlt_execNonLwstAplyDetailCsTypeList.removeAll();
        var tmpList = scwin.getLocalVar("sdFeeAmt");
        var execNonLwstAplyCsMaxByte = 0;
        for (var i = 0; i < tmpList.length; i++) {
            var rowData = {
                "label": tmpList[i].saTxt,
                "value": tmpList[i].saNmCd,
            };
            dlt_execNonLwstAplyDetailCsTypeList.setRowJSON(i, rowData);
            var labelByte = scwin.getStrByte(rowData.label);
            if (labelByte > execNonLwstAplyCsMaxByte) {
                execNonLwstAplyCsMaxByte = labelByte;
            }
        }
        scwin.handleSbxList(5, execNonLwstAplyCsMaxByte);
        sbx_execNonLwstCsType.setSelectedIndex(0);
        scwin.handleSbxList([5]);

        grp_prncmtLwstDvs.hide("");

        grp_clmnt.show("");
        spn_acsd.show("");
        sbx_ptntAcsdDvsCd.hide("");
        grp_acsd.show("");
        scwin.handleBtnList(2);

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        //ibx_clmntCnt.focus();

        scwin.fnChangeLabel(csTypCd, scwin.fnChangeDetailCsTypCd, "EXEC_NON_LWST")
    }//부동산경매, 채권압류 둥
    else if ("BK" == csTypCd || "CA" == csTypCd) {
        ///사건 종류 변경 확인
        if ("BK" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntJHWGJ1"));
        } else if ("CA" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntJHWGJ2"));
        }//집행비송부분 신청사건콤보 출력
        dlt_execNonLwstAplyDetailCsTypeList.removeAll();
        var tmpList = scwin.getLocalVar("sdFeeAmt");
        var execNonLwstAplyCsMaxByte = 0;
        for (var i = 0; i < tmpList.length; i++) {
            var rowData = {
                "label": tmpList[i].saTxt,
                "value": tmpList[i].saNmCd,
            };
            dlt_execNonLwstAplyDetailCsTypeList.setRowJSON(i, rowData);
            var labelByte = scwin.getStrByte(rowData.label);
            if (labelByte > execNonLwstAplyCsMaxByte) {
                execNonLwstAplyCsMaxByte = labelByte;
            }
        }
        scwin.handleSbxList(5, execNonLwstAplyCsMaxByte);
        sbx_execNonLwstCsType.setSelectedIndex(0);
        scwin.handleSbxList([5]);

        grp_prncmtLwstDvs.hide("");

        grp_clmnt.show("");
        spn_acsd.show("");
        sbx_ptntAcsdDvsCd.hide("");
        grp_acsd.show("");

        grp_intrps.show("");
        scwin.handleBtnList(3);
        grp_trgtOrg.hide("");

        //ibx_clmntCnt.focus();

        scwin.fnChangeLabel(csTypCd, scwin.fnChangeDetailCsTypCd, "EXEC_NON_LWST")
    }//채권배당, 과태료
    else if ("CB" == csTypCd || "GW" == csTypCd) {
        ///사건 종류 변경 확인
        if ("CB" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntJHWGJ3"));
        } else if ("GW" == csTypCd) {
            scwin.setLocalVar("sdFeeAmt", scwin.getLocalVar("sdFeeAmtCntGW1"));
        }//집행비송부분 신청사건콤보 출력
        dlt_execNonLwstAplyDetailCsTypeList.removeAll();
        var tmpList = scwin.getLocalVar("sdFeeAmt");
        var execNonLwstAplyCsMaxByte = 0;
        for (var i = 0; i < tmpList.length; i++) {
            var rowData = {
                "label": tmpList[i].saTxt,
                "value": tmpList[i].saNmCd,
            };
            dlt_execNonLwstAplyDetailCsTypeList.setRowJSON(i, rowData);
            var labelByte = scwin.getStrByte(rowData.label);
            if (labelByte > execNonLwstAplyCsMaxByte) {
                execNonLwstAplyCsMaxByte = labelByte;
            }
        }
        scwin.handleSbxList(5, execNonLwstAplyCsMaxByte);
        sbx_execNonLwstCsType.setSelectedIndex(0);
        scwin.handleSbxList([5]);

        grp_prncmtLwstDvs.hide("");


        ibx_clmntCnt.setValue("");
        grp_clmnt.hide("");

        ibx_acsdCnt.setValue("");
        spn_acsd.hide("");
        sbx_ptntAcsdDvsCd.hide("");
        grp_acsd.hide("");

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        scwin.handleBtnList(0);

        scwin.fnChangeLabel(csTypCd, scwin.fnChangeDetailCsTypCd, "EXEC_NON_LWST")
    }
    else {
        scwin.handleSbxList();

        grp_prncmtLwstDvs.hide("");

        grp_clmnt.show("");
        spn_acsd.show("");
        sbx_ptntAcsdDvsCd.hide("");
        grp_acsd.show("");

        scwin.handleBtnList(2);

        grp_intrps.hide("");
        grp_trgtOrg.hide("");

        //ibx_clmntCnt.focus();
        scwin.fnChangeLabel(csTypCd);
    }
}

/**
* 사건구분 변경에 따른 처리 Method
* ASIS-fnHgTypeChange, fnSinTypeChange, fnSosongGbnChange
*      fnWksSinTypeChange, fnWhpSinTypeChange, fnJhwgjSinTypeChange
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.fnChangeDetailCsTypCd = function (lwstTaskTypCd, newValue) {
    switch (lwstTaskTypCd) {
        case "APAL":
            scwin.setDefaultCnt(scwin.fnChangeLabel, "HG");
            break;
        case "CVLCS":
            scwin.setDefaultCnt();
            break;
        case "HSKP_APLY":
            scwin.setDefaultCnt();
            var hskpAplyCsType = sbx_hskpAplyCsType.getValue();
            if (hskpAplyCsType == psp.C.GAENMSIN || hskpAplyCsType == psp.C.GWANHALBGSIN) {
                grp_acsd.hide("");
                scwin.handleBtnList(1);
            } else {
                grp_acsd.show("");
                scwin.handleBtnList(2);
            }
            break;
        case "HSKP_EXCP":
            ibx_clmntCnt.setValue("");
            spn_rslt.setValue("");
            break;
        case "EXEC_NON_LWST":
            var execNonLwstAplyCsType = sbx_execNonLwstCsType.getValue();
            ibx_clmntCnt.setValue("");
            ibx_acsdCnt.setValue("");
            ibx_intrpsCnt.setValue("");
            ibx_trgtOrgAmt.setValue("");
            spn_rslt.setValue("");
            switch (sbx_csType.getValue()) {
                //부동산경매
                case "BK":
                    switch (execNonLwstAplyCsType) {
                        case psp.C.JHIUISIN:
                        case psp.C.KMGSIUISIN:
                        case psp.C.BDSINDOSIN:
                        case psp.C.BDSGRORDSIN_DOCCD:
                            grp_clmnt.show("");
                            grp_acsd.show("");
                            scwin.handleBtnList(2);
                            grp_intrps.hide("");
                            grp_trgtOrg.hide("");
                            spn_clmnt.setValue("신청인");
                            ibx_clmntCnt.setTitle("신청인수");
                            spn_acsd.setValue("피신청인");
                            ibx_acsdCnt.setTitle("피신청인수");
                            break;
                        default:
                            grp_clmnt.hide("");
                            grp_acsd.hide("");
                            grp_intrps.show("");
                            scwin.handleBtnList(3);
                            grp_trgtOrg.hide("");
                            spn_intrps.setValue("이해관계인");
                            ibx_intrpsCnt.setTitle("이해관계인수");
                            break;
                    }
                    break;
                case "CA":
                    switch (execNonLwstAplyCsType) {
                        case "311":
                            grp_clmnt.show("");
                            grp_acsd.show("");
                            scwin.handleBtnList(2);
                            grp_intrps.hide("");
                            grp_trgtOrg.hide("");
                            spn_clmnt.setValue("신청인");
                            ibx_clmntCnt.setTitle("신청인수");
                            spn_acsd.setValue("상대방");
                            ibx_acsdCnt.setTitle("상대방수");
                            break;
                        case psp.C.WGJETCSIN:
                        case psp.C.ARGJCGBWBKSIN:
                        case psp.C.BDYGCGJARCGCSHGSIN:
                            grp_clmnt.show("");
                            grp_acsd.show("");
                            scwin.handleBtnList(2);
                            grp_intrps.hide("");
                            grp_trgtOrg.hide("");
                            spn_clmnt.setValue("신청인");
                            ibx_clmntCnt.setTitle("신청인수");
                            spn_acsd.setValue("피신청인");
                            ibx_acsdCnt.setTitle("피신청인수");
                            break;
                        default:
                            grp_clmnt.show("");
                            grp_acsd.show("");
                            grp_intrps.show("");
                            scwin.handleBtnList(3);
                            grp_trgtOrg.hide("");
                            spn_clmnt.setValue("채권자");
                            ibx_clmntCnt.setTitle("채권자수");
                            spn_acsd.setValue("채무자");
                            ibx_acsdCnt.setTitle("채무자수");
                            spn_intrps.setValue("제3채무자");
                            ibx_intrpsCnt.setTitle("제3채무자수");
                            break;
                    }
                    break;
                //채권배당
                case "CB":
                    grp_clmnt.hide("");
                    grp_acsd.hide("");
                    grp_intrps.hide("");
                    grp_trgtOrg.hide("");
                    scwin.handleBtnList(0);
                    break;
                //재산명시/감치
                case "JMKC":
                    switch (execNonLwstAplyCsType) {
                        case "99":
                            grp_clmnt.show("");
                            grp_acsd.show("");
                            scwin.handleBtnList(2);
                            grp_intrps.hide("");
                            grp_trgtOrg.hide("");
                            spn_clmnt.setValue("신청인");
                            ibx_clmntCnt.setTitle("신청인수");
                            spn_acsd.setValue("피신청인");
                            ibx_acsdCnt.setTitle("피신청인수");
                            break;
                        default:
                            grp_clmnt.show("");
                            grp_acsd.show("");
                            scwin.handleBtnList(2);
                            grp_intrps.hide("");
                            grp_trgtOrg.hide("");
                            spn_clmnt.setValue("신청인");
                            ibx_clmntCnt.setTitle("신청인수");
                            spn_acsd.setValue("상대방");
                            ibx_acsdCnt.setTitle("상대방수");
                            break;
                    }
                    break;
                //재산조회/채무불이행자명부
                case "JSCM":
                    switch (execNonLwstAplyCsType) {
                        case "502":
                            grp_clmnt.hide("");
                            grp_acsd.hide("");
                            grp_intrps.hide("");
                            grp_trgtOrg.show("");
                            scwin.handleBtnList(4);
                            break;
                        case "323G":
                            grp_clmnt.hide("");
                            grp_acsd.hide("");
                            grp_intrps.hide("");
                            grp_trgtOrg.hide("");
                            scwin.handleBtnList(0);
                            break;
                        default:
                            grp_clmnt.show("");
                            grp_acsd.show("");
                            scwin.handleBtnList(2);
                            grp_intrps.hide("");
                            grp_trgtOrg.hide("");
                            spn_clmnt.setValue("신청인");
                            ibx_clmntCnt.setTitle("신청인수");
                            spn_acsd.setValue("상대방");
                            ibx_acsdCnt.setTitle("상대방수");
                            break;
                    }
                    break;
                //그 밖의 집행
                case "GJ":
                    grp_clmnt.show("");
                    grp_acsd.show("");
                    scwin.handleBtnList(2);
                    grp_intrps.hide("");
                    grp_trgtOrg.hide("");
                    spn_clmnt.setValue("신청인");
                    ibx_clmntCnt.setTitle("신청인수");
                    spn_acsd.setValue("피신청인");
                    ibx_acsdCnt.setTitle("피신청인수");
                    break;
                // 과태료
                case "GW":
                    grp_clmnt.hide("");
                    grp_acsd.hide("");
                    grp_intrps.hide("");
                    grp_trgtOrg.hide("");
                    scwin.handleBtnList(0);
                    break;
                // 비송
                case "BSD":
                case "BSH":
                    grp_clmnt.show("");
                    grp_acsd.show("");
                    scwin.handleBtnList(2);
                    grp_intrps.hide("");
                    grp_trgtOrg.hide("");
                    spn_clmnt.setValue("신청인");
                    ibx_clmntCnt.setTitle("신청인수");
                    spn_acsd.setValue("피신청인");
                    ibx_acsdCnt.setTitle("피신청인수");
                    break;
            }
            break;
        case "RHBL_BNKP":
            var rhblBnkpAplyCsType = sbx_rhblBnkpCsType.getValue();
            ibx_clmntCnt.setValue("1");
            ibx_acsdCnt.setValue("1");
            spn_rslt.setValue("");
            var ofdocDvsCd = dma_csCalcInfo.get("ofdocDvsCd");
            switch (rhblBnkpAplyCsType) {
                case "521":
                case "522":
                    spn_clmnt.setValue("당사자");
                    ibx_clmntCnt.setTitle("당사자수");
                    spn_acsd.setValue("상대방");
                    ibx_acsdCnt.setTitle("상대방수");
                    break;
                case "524":
                case "528":
                case "529":
                    if (rhblBnkpAplyCsType == "528" && ofdocDvsCd == psp.C.INHERFTPSSIN) {
                        break;
                    }
                    spn_clmnt.setValue("당사자");
                    ibx_clmntCnt.setTitle("당사자수");
                    break;
                default:
                    spn_clmnt.setValue("채권자");
                    ibx_clmntCnt.setTitle("채권자수");
                    break;
            }
            grp_clmnt.show("");
            scwin.handleBtnList(1);
            grp_acsd.hide("");
            if (rhblBnkpAplyCsType == "521") {
                switch (sbx_csType.getValue()) {
                    case "PH":
                    case "BH":
                    case "BF":
                    case "NH":
                        grp_acsd.show("");
                        scwin.handleBtnList(2);
                        break;
                    default:
                        break;
                }
            }
            break;
    }
}

/**
* 원고 피고 텍스트 변경  Method
* ASIS-fnChangeWPcntTxtBySaType, fnChangeWPcntTxtByHgType
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.06.22.   김기오       [NELS]최초 생성
* ============= ============ ==========================
*/
scwin.fnChangeLabel = function (csDvsCd, callbackFn, callbackParam) {
    var clmntTxt = "";
    var acsdTxt = "";
    var intrpsTxt = "";

    //사건구분별 원/피고 표시명
    if (csDvsCd == "HG") {
        var tmpList = scwin.getLocalVar("sdFeeHgCnt");
        for (var i = 0; i < tmpList.length; i++) {
            if (tmpList[i].docCd == sbx_apalCsType.getValue()) {
                clmntTxt = tmpList[i].wongoTxt;
                acsdTxt = tmpList[i].pigoTxt;
                break;
            }
        }
    } else {
        var tmpList = scwin.getLocalVar("sdFeeCalcBySaGbn");
        for (var i = 0; i < tmpList.length; i++) {
            if (tmpList[i].saGbnValue == csDvsCd || tmpList[i].saGbnValue == "") {
                clmntTxt = tmpList[i].wongoTxt;
                acsdTxt = tmpList[i].pigoTxt;
                if (csDvsCd == "BK") {
                    intrpsTxt = tmpList[i].ihchamTxt;
                } else if (csDvsCd == "CA") {
                    intrpsTxt = tmpList[i].pigoTxt1;
                }
                break;
            }
        }
    }
    spn_clmnt.setValue(clmntTxt === undefined ? spn_clmnt.getValue() : clmntTxt);
    spn_acsd.setValue(acsdTxt === undefined ? spn_acsd.getValue() : acsdTxt);
    ibx_clmntCnt.setTitle(clmntTxt+"수");
    ibx_acsdCnt.setTitle(acsdTxt+"수");

    if (csDvsCd == "BK" || csDvsCd == "CA") {
        spn_intrps.setValue(intrpsTxt);
        ibx_intrpsCnt.setTitle(intrpsTxt+"수");
    }
    //TODO 20230622 고민 => hide 되지 않은 element들에 대해서 처리하면 되는 것 아닌지
    var preFix = "사건 종류";
    var suffix = "계산버튼을 눌러 주세요.";
    var guideStr = "";
    switch (csDvsCd) {
        case "SC":
            guideStr = ", 본안 소송구분, " + clmntTxt + ", " + acsdTxt + "의 수를 입력하고 ";
            break;
        case "WPT":
            guideStr = ", 피고구분, " + clmntTxt + ", " + acsdTxt + "의 수를 입력하고 ";

            break;
        case "SG_WPT":
            guideStr = ", 피상고인구분, " + clmntTxt + ", " + acsdTxt + "의 수를 입력하고 ";

            break;
        case "WKS_BS4":
            guideStr = ", " + clmntTxt + "의 수를 입력하고 ";
            break;
        case "PH":
        case "PF":
        case "BH":
        case "BF":
        case "NH":
            guideStr = ", " + acsdTxt + "의 수를 입력하고 ";
            break;
        case "BK":
        case "CA":
            guideStr = ", " + clmntTxt + ", " + acsdTxt + "," + intrpsTxt + "의 수를 입력하고 ";
            break;
        case "CB":
        case "GW":
            guideStr = "를 선택하고 ";
            break;
        case "JSCM":
            if (dma_csCalcInfo.get("intgCsNmCd") == "502") {
                guideStr = ", 대상기관 금액을 입력하고 ";
            } else {
                guideStr = ", " + clmntTxt + ", " + acsdTxt + "의 수를 입력하고 ";
            }
            break;
        case "HG":
            if (sbx_elctnLwstTaskTypCd.getValue() == psp.C.SO_KIND_PHP) {
                guideStr = ", 본안 소송구분, " + clmntTxt + "의 수를 입력하고 ";
            } else {
                guideStr = ", 본안 소송구분, " + clmntTxt + ", " + acsdTxt + "의 수를 입력하고 ";
            }
            break;
        default:
            guideStr = ", " + clmntTxt + ", " + acsdTxt + "의 수를 입력하고 ";
            break;
    }
    tbx_calcGuide.setValue(preFix + guideStr + suffix);

    if (!scutilo.isEmpty(callbackFn) && !scutilo.isEmpty(callbackParam)) {
        callbackFn(callbackParam);
    }

}

/**
 * 송달료 계산
 * ASIS-calcSdFee
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.23.   김기오       [NELS]최초 생성
 *  2024.01.04.   김기오       대상기관 로직 수정
 * ============= ============ ==========================
 */
scwin.calcDlvrChrg = function () {
    var lwstTaskTypCd = sbx_elctnLwstTaskTypCd.getValue();
    var csDvsCd = sbx_csType.getValue();
    var hskpAplyCsType = sbx_hskpAplyCsType.getValue();
    var rhblBnkpCsType = sbx_rhblBnkpCsType.getValue();
    var execNonLwstAplyCsType = sbx_execNonLwstCsType.getValue();
    var intgCsNmCd = sbx_execNonLwstCsType.getValue();

    var acsdCnt = 0;
    var dlvrChrg = -1;
    var dlvrCnt = 0;
    var dlvrBtprtCnt = 0;

    //송달료 납부면제기준
    var dlvrChrgPayRule = Number(scwin.getLocalVar("sdFeeNbRule"));

    var csDvsList = scwin.getLocalVar("sdFeeCalcBySaGbn");
    var apalTypeList = scwin.getLocalVar("sdFeeHgCnt");
    var cvlcsAplyCsList = scwin.getLocalVar("sdFeeSinCntWCV");
    var hskpAplyCsList = scwin.getLocalVar("sdFeeSinCntWKS");
    var hskpBsDetailCsList = scwin.getLocalVar("sdFeeBSCntWKS");
    //회생파산, 집행비송을 같이 사용중
    var rhblBnkExecNonLwstCsList = scwin.getLocalVar("sdFeeAmt");

    if (csDvsCd == "WKS_BS4" || (sbx_elctnLwstTaskTypCd == "WHP" && csDvsCd == "HG") || (csDvsCd == "WKS_SC" && (hskpAplyCsType == psp.C.GAENMSIN || hskpAplyCsType == psp.C.GWANHALBGSIN))) {
        //validw
        psp.validate_wm("grp_clmnt");
    } else if ("CB" == csDvsCd || "GW" == csDvsCd || ("JSCM" == csDvsCd && ("502" == intgCsNmCd || "323G" == intgCsNmCd))) {

    } else if ("BK" == csDvsCd && psp.C.JHIUISIN != intgCsNmCd && psp.C.KMGSIUISIN != intgCsNmCd && psp.C.BDSINDOSIN != intgCsNmCd && psp.C.BDSGRORDSIN_DOCCD != intgCsNmCd) {
        psp.validate_wm("grp_intrps");
    } else {
        if (!psp.validate_wm("grp_clmnt") || !psp.validate_wm("grp_acsd")) {
            return false;
        }
    }

    //공동소송참가신청서
    //본소 원고 + 피고
    if (scwin.getLocalVar("isJintLwst")) {
        acsdCnt = Number(ibx_clmntCnt.getValue()) + Number(ibx_acsdCnt.getValue());
        scwin.setLocalVar("isJintLwst", false);
        dlvrBtprtCnt = acsdCnt;
    }

    for (var i = 0; i < csDvsList.length; i++) {

        if (csDvsList[i].saGbnValue == csDvsCd) {

            //2011.07.12 [CJS2-2] (재)항고 및 신청사건추가 코아시스템 박상기 시작
            if (csDvsCd == "HG") {
                //문서구분코드
                var docCd = sbx_apalCsType.getValue();
                var dlvrCnt = 0;
                for (var i = 0; i < apalTypeList.length; i++) {
                    if (docCd == apalTypeList[i].docCd) {
                        dlvrCnt = apalTypeList[i].cnt;
                        break;
                    }
                }
                var prncmtLwstDvsCd = sbx_prncmtLwstDvsCd.getValue(); //본안소송구분
                if (psp.C.PAPER_SOSONG == prncmtLwstDvsCd) {//종이소송이면 (항고인+상대방)
                    acsdCnt = Number(ibx_clmntCnt.getValue()) + Number(ibx_acsdCnt.getValue());
                    dlvrBtprtCnt = acsdCnt;
                }

                if (dlvrCnt > dlvrChrgPayRule) {
                    if (dlvrBtprtCnt == 0) {
                        dlvrBtprtCnt = Number(ibx_acsdCnt.getValue());
                    }
                    // 소송유형 가사, 행정이고 상대방이 없는 경우 항고인 수로 계산
                    if (dlvrBtprtCnt == 0) { //소송유형과 무관하게 항고인 수로 계산하도록 수정
                        dlvrBtprtCnt = Number(ibx_clmntCnt.getValue());
                    }

                } else {
                    if (dlvrBtprtCnt == 0) {
                        dlvrBtprtCnt = Number(ibx_clmntCnt.getValue()) + Number(ibx_acsdCnt.getValue());
                    }
                }

                dlvrChrg = dlvrBtprtCnt * psp.C.SD_FEE * Number(dlvrCnt); //송달료계산
                break;
            }
            //신청사건, 보전처분
            else if (csDvsCd == "SC" || csDvsCd == "BJ") {

                var saNmCd = sbx_aplyCsType.getValue(); //사건명코드
                var scinCnt = 0;
                var sdbangCnt = 0;

                var prncmtLwstDvsCd = sbx_prncmtLwstDvsCd.getValue(); //본안소송구분

                //민사인 경우
                if (psp.C.SO_KIND_PCV == lwstTaskTypCd) {
                    for (var i = 0; i < cvlcsAplyCsList.length; i++) {
                        if (saNmCd == cvlcsAplyCsList[i].saNmCd) {
                            scinCnt = cvlcsAplyCsList[i].scinCnt; //신청인수
                            sdbangCnt = cvlcsAplyCsList[i].sdbangCnt; //상대방(피신청인)수
                            break;
                        }
                    }
                    //가처분신청서 임시지위인 경우 8로 세팅
                    var saTxt = (sbx_aplyCsType.getItemArray()[sbx_aplyCsType.getSelectedIndex()]).label;
                    if ("가처분신청서(임시지위)" == saTxt) {
                        scinCnt = 8;
                        sdbangCnt = 8;
                    }

                    dlvrCnt = sdbangCnt;
                    //종이소송 : ((신청인수 * 신청인송달회수) + (상대방수 * 상대방송달회수)) * 송달료
                    if (psp.C.PAPER_SOSONG == prncmtLwstDvsCd) {
                        // 가압류, 가처분신청서의 경우 원심사건의 사건구분과 관계없이 무조건 전자사건으로 처리해야 함
                        if (psp.C.BJGAAPSIN == saNmCd || psp.C.BJGACHUSIN == saNmCd) {
                            //dlvrChrg = (Number(ibx_acsdCnt.getValue()) * Number(sdbangCnt)) * psp.C.SD_FEE;
                        } else {
                            dlvrBtprtCnt = Number(ibx_clmntCnt.getValue()) + Number(ibx_acsdCnt.getValue());
                            dlvrChrg = ((Number(ibx_clmntCnt.getValue()) * Number(scinCnt)) +
                                (Number(ibx_acsdCnt.getValue()) * Number(sdbangCnt))) * psp.C.SD_FEE;
                        }

                    }
                    if (dlvrCnt > dlvrChrgPayRule) {
                        //공시최고신청서는 신청인이 기준임
                        if (psp.C.GONGSICHOIGO == saNmCd) {
                            dlvrBtprtCnt = Number(ibx_clmntCnt.getValue());
                        }
                        if (dlvrBtprtCnt == 0) {
                            dlvrBtprtCnt = Number(ibx_acsdCnt.getValue());
                        }
                        if (dlvrBtprtCnt == 0) {
                            dlvrBtprtCnt = Number(ibx_clmntCnt.getValue());
                        }
                    } else {
                        if (dlvrBtprtCnt == 0) {
                            dlvrChrg = ((Number(ibx_clmntCnt.getValue()) * Number(scinCnt)) + (Number(ibx_acsdCnt.getValue()) * Number(sdbangCnt))) * psp.C.SD_FEE;
                        }
                    }
                } else {
                    dlvrCnt = Number(csDvsList[i].multiValue);
                    //종이소송 : (신청인수+피신청인수) * 송달회수 * 송달료
                    if (psp.C.PAPER_SOSONG == prncmtLwstDvsCd) {
                        dlvrBtprtCnt = Number(ibx_clmntCnt.getValue()) + Number(ibx_acsdCnt.getValue());
                    }
