                    if (rhblBnkExecNonLwstCsList[y].saNmCd == execNonLwstAplyCsType) {
                        //(당사자수(신청인, 피신청인) X 4회) * 송달료
                        dlvrChrg = (Number(ibx_acsdCnt.getValue()) + Number(ibx_clmntCnt.getValue())) * psp.C.SD_FEE * rhblBnkExecNonLwstCsList[y].multiValue;
                        break;
                    }
                }
                break;
            }
            //비송합의 사건
            else if ("BSH" == csDvsCd) {
                for (var y = 0; y < rhblBnkExecNonLwstCsList.length; y++) {
                    if (rhblBnkExecNonLwstCsList[y].saNmCd == execNonLwstAplyCsType) {
                        //(당사자수(신청인, 피신청인) X 3회) * 송달료
                        dlvrChrg = (Number(ibx_acsdCnt.getValue()) + Number(ibx_clmntCnt.getValue())) * psp.C.SD_FEE * rhblBnkExecNonLwstCsList[y].multiValue;
                        break;
                    }
                }
                break;
            }
            //윤중석, 2014.07.23 [CJS6] 민사집행인 경우의  송달료 계산 추가 End
            dlvrCnt = Number(csDvsList[i].multiValue);
            if (dlvrCnt > dlvrChrgPayRule) {
                dlvrBtprtCnt = Number(ibx_acsdCnt.getValue());
            } else {
                dlvrBtprtCnt = Number(ibx_acsdCnt.getValue()) + Number(ibx_clmntCnt.getValue());
            }
            dlvrChrg = dlvrBtprtCnt * psp.C.SD_FEE * dlvrCnt;
            break;
        }
    }
    var commAmt = scwin.getDotFormattedNumber(dlvrChrg.toFixed(0), 3, "원");
    var amtLocaleString = psputils.convertMoneytoStr((dlvrChrg.toFixed(0)).toString());
    spn_rslt.setValue("송달료는 " + '<b><font color="045abd">' + commAmt + " (" + amtLocaleString + ")</font></b> 입니다.");

}

