/**
 * 특허 피고구분 변경에 따른 Method
 * ASIS-fnPigoGbnChange
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.23.   김기오       [NELS]최초 생성
 *  2025.11.06.                [25A-PSP-0081] 특허청의 지식재산처 승격에 따른 개선 
 * ============= ============ ==========================
 */
scwin.fnChangePtntAcsdDvsCd = function (ptntAcsdDvsCd) {
    if (scutilo.isEmpty(ptntAcsdDvsCd)) {
        ptntAcsdDvsCd = sbx_ptntAcsdDvsCd.getValue();
    }
    var csType = sbx_csType.getValue();
    scwin.setDefaultCnt();
    var ascdCnt = 0;
    var intDlvrAmt = 0;

    //피고가 지식재산처장일 경우
    if (ptntAcsdDvsCd == "ptntChief") {
        grp_clmnt.hide("");
        ibx_acsdCnt.hide("");
        spn_acsdCnt.hide("");
        scwin.handleBtnList();
        if (csType == "WPT") {
            tbx_calcGuide.setValue("사건 종류와 피고구분을 선택해 주세요.");
        }
        else {
            tbx_calcGuide.setValue("사건 종류와 피상고인구분을 선택해 주세요.");
        }
        var tmpList = scwin.getLocalVar("sdFeeCalcBySaGbn");
        for (var i = 0; i < tmpList.length; i++) {
            if (csType == tmpList[i].saGbnValue) {
                acsdCnt = 1; //피고는 지식재산처장 한명
                intDlvrAmt = acsdCnt * psp.C.SD_FEE * Number(tmpList[i].multiValue1);
                break;
            }
        }
        var dlvrChrg = scwin.getDotFormattedNumber(intDlvrAmt.toFixed(0), 3, "원");
        var amtLocaleString = psputils.convertMoneytoStr((intDlvrAmt.toFixed(0)).toString());
        spn_rslt.setValue("송달료는 " + '<b><font color="045abd">' + dlvrChrg + "( " + amtLocaleString + ")</font></b> 입니다.");
    } //피고가 지식재산처장이 아닐경우 송달료 계산식에 따라 계산.
    else if (ptntAcsdDvsCd == "ptntEtc") {
        grp_clmnt.show("");
        ibx_acsdCnt.show("");
        spn_acsdCnt.show("");
        scwin.handleBtnList(2);

        scwin.fnChangeLabel(csType);
    }
}

/**
 * 금액 콤마처리 Method
 * ASIS-ECF000.cfDotNum
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.23.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getDotFormattedNumber = function (paramNum, thresholdPoint, suffixStr) {
    var numToStr = "";
    var strLength = 0;
    var formattedResult = "";

    if (isNaN(paramNum)) {
        return "0" + suffixStr;
    }

    numToStr = paramNum.toString();
    strLength = numToStr.length;

    if (strLength > thresholdPoint) {
        for (var i = 0; i < strLength; i++) {
            if (((strLength - i) % thresholdPoint) == 0 && i != 0) {
                formattedResult += "," + numToStr.substr(i, 1);
            } else {
                formattedResult += numToStr.substr(i, 1);
            }
        }
        formattedResult += suffixStr;
    } else {
        formattedResult = numToStr + suffixStr;
    }
    return formattedResult;
}

