/**
 * 문자열의 byte를 반환하는 Method
 * param : str(필수, selectbox의 label)
 * 유니코드값이 128이하일 경우(개행문자 제외) 1byte, 이외의 경우 2byte로 계산
 * accumulator : 누적되는 return 값, currentValue : 처리할 현재
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.27.   김기오       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getStrByte = function (str) {
    return str.split('')
        .map(char => char.charCodeAt(0))
        .reduce((accumulator, currentValue) => (accumulator + ((currentValue === 10) ? 2 : ((currentValue >> 7) ? 2 : 1))), 0);
}

