/**
 * 송달료 계산 기본 정보 조회 callback
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.20.   김기오       [NELS]최초 생성
 *  2025.11.06.                [25A-PSP-0081] 특허청의 지식재산처 승격에 따른 개선 
 * ============= ============ ==========================
 */
scwin.sbm_retrieveDlvrCalcBasInfo_submitdone = function (e) {
    var responseText = JSON.parse(e.responseText);
    var dataObj = responseText.data;
    var dlvrAmtCalcBasInfo = dataObj.dma_dlvrAmtCalcBasInfo;
    //AS-IS로직 그대로, 변수명 비교하여 같은 값일 경우 API결과 반영
    Object.keys(dlvrAmtCalcBasInfo).forEach(function (key1) {
        Object.keys(scwin.dlvrAmtInfo).forEach(function (key2) {
            if (key1 === key2) {
                scwin.dlvrAmtInfo[key2] = dlvrAmtCalcBasInfo[key1];
            }
        })
    })

    spn_calcDlvrGuide.setValue("1. 전자소송시스템을 이용한 소송의 진행에 동의한 등록사용자의 경우 자신을 제외한 나머지 당사자 수를 기준으로 송달료를 납부하시면 되고 그 계산 방식은 아래와 같습니다. 단, 1인당 송달료가 "
        + scwin.getLocalVar("sdFeeNbRule") + "회분 이하인 경우 전체 당사자 수를 기준으로 납부합니다.")
    spn_giveOrdGuide.setValue("(채권자수 + 채무자수) X 송달료 " + scwin.getLocalVar("dcMultiValue") + "회분");

    tbx_warnPtntChief.setValue("※ 유의사항 - 특허1심사건의 피고가 지식재산처장인 경우에는 "
        + scwin.getLocalVar("strDlvrChrgForWPT") + "(6회분)으로 모든 사건에 동일하게 적용됩니다. 특허상고심사건의 피상고인이 지식재산처장인 경우에는 "
        + scwin.getLocalVar("strDlvrChrgForWPT") + "(6회분)으로 모든 사건에 동일하게 적용됩니다.");



    if (!scutilo.isEmpty(dma_parentInfo.get("elpEcdocNo"))) {
        scwin.retrieveDetailAmtInfo();
    } else {
        sbx_elctnLwstTaskTypCd.setValue(dma_parentInfo.get("elctnLwstTaskTypCd"));
        console.log(sbx_elctnLwstTaskTypCd.getValue());
        scwin.fnChangeLwstTaskTypCd();
    }
};

/**
 * 송달료 계산 사건 정보 조회 callback
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.20.   김기오       [NELS]최초 생성
 *  2024.04.09.   김기오       사건구분수정 이벤트 추가
 * ============= ============ ==========================
 */
scwin.sbm_retrieveCsCalcInfo_submitdone = function (e) {
    var lwstTypCd = dma_csCalcInfo.get("lwstTypCd");
    var csType = dma_csCalcInfo.get("saType");
    var ofdocDvsCd = dma_csCalcInfo.get("ofdocDvsCd");
    var intgCsNmCd = dma_csCalcInfo.get("intgCsNmCd");
    var intgCsNmDtlCd = dma_csCalcInfo.get("intgCsNmDtlCd");
    var clmntCnt = dma_csCalcInfo.get("clmntCnt");
    var acsdCnt = dma_csCalcInfo.get("acsdCnt");
    var tmprStndng = dma_csCalcInfo.get("imsi");
    dma_parentInfo.set("elctnLwstTaskTypCd", dma_csCalcInfo.get("elctnLwstTaskTypCd"));

    //소송유형 세팅
    sbx_elctnLwstTaskTypCd.setValue(dma_parentInfo.get("elctnLwstTaskTypCd"));
    //sbx_csType.setValue(csType);
    scwin.fnChangeLwstTaskTypCd(csType);
    sbx_prncmtLwstDvsCd.setValue(lwstTypCd);

    sbx_csType.setValue(csType);
    scwin.fnChangeCsTypCd();

    //항고, 재항고사건
    if ("HG" == csType) {
        scwin.setDefaultCnt();
    }

    var hgCsList = scwin.getLocalVar("sdFeeHgCnt");
    for (var i = 0; i < hgCsList.length; i++) {
        if (ofdocDvsCd == hgCsList[i].docCd) {
            sbx_apalCsType.setValue(ofdocDvsCd);
            scwin.fnChangeDetailCsTypCd("APAL");
            break;
        }
    }

    //신청사건
    if ("SC" == csType) {
        scwin.setDefaultCnt();
        if (ofdocDvsCd == psp.C.JAESIMSIN) {
            //준재심신청서의 경우 사건명코드로 판단할 수 없음.
            sbx_aplyCsType.setValue("CANTFIX1");
            scwin.fnChangeDetailCsTypCd("CVLCS");
        } else {
            if (psp.C.SO_KIND_PCV == sbx_elctnLwstTaskTypCd.getValue()) {
                var cvlcsAplyCsList = scwin.getLocalVar("sdFeeSinCntWCV");
                for (var i = 0; i < cvlcsAplyCsList.length; i++) {
                    if ("Im" == tmprStndng) {
                        if (intgCsNmCd == cvlcsAplyCsList[i].saNmCd + "Im") {
                            sbx_aplyCsType.setValue(intgCsNmCd);
                            scwin.fnChangeDetailCsTypCd("CVLCS");
                        }
                    } else {
                        if (intgCsNmCd == cvlcsAplyCsList[i].saNmCd) {
                            sbx_aplyCsType.setValue(intgCsNmCd);
                            scwin.fnChangeDetailCsTypCd("CVLCS");
                        }
                    }
                }
            }
        }
    }

    // 가사비송
    if ("WKS_BS4" == csType) {

        var isMatched = false;
        var hkspNonLwstCsList = scwin.getLocalVar("sdFeeBSCntWKS");

        //세부사건명으로 존재하는지 먼저 확인
        for (var i = 0; i < hkspNonLwstCsList.length; i++) {
            if (intgCsNmDtlCd == hkspNonLwstCsList[i].saNmCd) {
                sbx_hskpCsType.setValue(intgCsNmDtlCd);
                isMatched = true;
                break;
            }
        }

        //존재하지 않는 경우
        if (!isMatched) {
            //사건명으로 존재하는지 확인
            for (var i = 0; i < hkspNonLwstCsList.length; i++) {
                if (intgCsNmCd == hkspNonLwstCsList[i].saNmCd) {
                    sbx_hskpCsType.setValue(intgCsNmCd);
                    isMatched = true;
                    break;
                }
            }

            //모두 존재하지 않는 경우
            if (!isMatched) {
                sbx_hskpCsType.setValue("OTHERS");
            }
        }
    }

    //가사 신청사건
    if ("WKS_SC" == csType) {

        var isMatched = false;
        var hskpAplyCsList = scwin.getLocalVar("sdFeeSinCntWKS");
        for (var i = 0; i < hskpAplyCsList.length; i++) {
            if (intgCsNmCd == hskpAplyCsList[i].saNmCd) {
                sbx_hskpAplyCsType.setValue(intgCsNmCd);
                scwin.fnChangeDetailCsTypCd("HSKP_APLY");
                isMatched = true;
                break;
            }
        }
        if (!isMatched) {
            sbx_hskpAplyCsType.setValue("OTHERS");
        }
    }
    ibx_clmntCnt.setValue(clmntCnt);
    ibx_acsdCnt.setValue(acsdCnt);

    // 공동소송참가신청서(원고)의 송달료 계산, (원고수 + 피고수) X 해당사건의 송달료 회분
    if ("true" == dma_csCalcInfo.get("calculAll")) {
        scwin.setLocalVar("isJintLwst", true);
    }

    if (!scutilo.isEmpty(csType) && !scutilo.isEmpty(acsdCnt)) {
        scwin.calcDlvrChrg();
    }
};
